      "expected_output": "length=2\ndirty=false\n"
    },
    {
      "input": {
        "op": "array_state",
        "name": "foo",
        "subscription": {"dirty": true},
        "initialValues": {"foo": ["a", "b", "c", "d"]},
        "report": ["length", "dirty"]
